  "결제 후 7일 이내라도 해당 결제로 지급된 유상 크레딧을 일부라도 사용한 경우에는 환불이 불가하며, 미사용 잔액에 대한 부분 환불도 제공되지 않습니다.": "If you have used any part of the paid credit paid for the payment even within 7 days after payment, no refund is possible, and no partial refund is provided for the unused balance.",
  "결제 후 7일 이내에 라이브 방송을 단 1회도 송출하지 않았고, 비즈니스 타임라인 등 유료 기능 또한 이용하지 않은 경우에 한하여 「전자상거래 등에서의 소비자보호에 관한 법률」 제17조에 따른 청약철회로 전액 환불이 가능합니다.": "A full refund is possible by cancellation of subscription pursuant to Article 17 of the Act on Consumer Protection in Electronic Commerce, etc., only if no live broadcast has been broadcast within 7 days of payment and paid functions such as business timeline have not been used.",
  "결제 후 7일이 경과한 경우에는 유상 크레딧 사용 여부와 관계없이 환불이 불가합니다. 다만 회사의 귀책사유로 서비스가 정상 제공되지 않았거나 관련 법령상 환불이 필요한 경우에는 법령과 회사의 합리적인 기준에 따라 처리합니다.": "If 7 days have passed since payment, refunds are not possible regardless of whether paid credit was used. However, if the service is not properly provided due to the company's fault or a refund is required under relevant laws, it will be processed in accordance with the law and the company's reasonable standards.",
