  "광고비가 들어오는 캠페인의 예산과, 브랜드 제시가에서 인플루언서 단가를 뺀 우리 순수익입니다.": "This is our net profit obtained by subtracting the influencer unit price from the budget of the campaign that includes advertising costs and the brand price.",
  "광고비가 없는 협업은 제안 성사율이 낮아 담당자 리스트업을 붙이지 않습니다. 지원자 명단에서 브랜드가 직접 고르는 방식이라 후보 풀은 표시하지 않습니다.": "For collaborations without advertising fees, the proposal success rate is low, so a list-up of the person in charge is not included. The candidate pool is not displayed as the brand selects directly from a list of applicants.",
