  "링크 버튼 설정": "Link button settings",
  "링크 버튼은 카드 형태로 전송됩니다. 인스타그램 모바일 앱에서만 표시되고 웹(instagram.com) DM 화면에서는 보이지 않습니다.": "The link button is sent in card form. It is only displayed on the Instagram mobile app and is not visible on the web (instagram.com) DM screen.",
  "링크 생성, 프로필 편집, 비즈니스 제안서 관리 등 기본적인 멀티링크 기능은 회원가입 후 무료로 이용할 수 있습니다.": "Basic multi-link functions such as link creation, profile editing, and business proposal management can be used for free after signing up.",
