  "키워드별 자동 응답 · 발송 이력 확인 · 수동 DM 발송": "Keyword-based auto replies · delivery history · manual DM sending",
  "인사이트 메뉴": "Insights menu",
  "이용 — 릴스 조회 · 도달 · 저장 지표를 한눈에": "included — reel views, reach and saves at a glance",
  "디엠 자동화는 인스타그램 댓글에 반응해 자동으로 DM을 보내고, 키워드별 응답 문구와 발송 이력을 관리할 수 있습니다. 인스타그램 프로페셔널(비즈니스 · 크리에이터) 계정 연동이 필요합니다.": "DM automation replies to Instagram comments by sending a DM automatically, and lets you manage the reply text per keyword along with the delivery history. It requires an Instagram professional (business or creator) account connection.",
  ": 릴스 조회 · 도달 · 저장 지표와 반응 좋은 릴스 TOP 5, AI 콘텐츠 코칭을 함께 제공합니다. 비즈니스 계정은 우리 계정을 태그한 인플루언서 콘텐츠까지 인사이트에서 볼 수 있습니다.": ": reel views, reach and saves, the top 5 best-performing reels and AI content coaching, all in one place. Business accounts can also see the influencer content that tagged them in Insights.",
  "구독을 시작하면 영상 업로드 · 콘텐츠 업로드 등 스탠다드 기능과 협업 타임라인 AI 어시스턴트, 콘텐츠 기획 AI, 인스타그램 디엠 자동화, 인사이트 메뉴(릴스 지표 · 릴스 TOP 5 · AI 코칭)가 즉시 활성화됩니다.": "Once the subscription starts, standard features such as video and content uploads, the collaboration timeline AI assistant, the content planning AI, Instagram DM automation and the Insights menu (reel metrics · top 5 reels · AI coaching) are activated immediately.",
  "모든 멤버십 플랜": "All membership plans",
  "모든 사용자": "All users",
  "모든 채널에 담당자 답변이 마지막입니다.": "For all channels, the representative's response is final.",
  "모든 최근 게시물 댓글 작성자": "All recent posts Commenters",
  "모든 캠페인에 담당자가 있습니다.": "Every campaign has a representative.",
  "모든 캠페인이 어느 단계에서 멈춰 있고 누가 맡고 있는지 한 표로 봅니다. 담당자를 바로 바꿀 수 있고, 아래 협업 콘솔에서는 조건 확정·제출물 검수·정산 예약을 처리합니다.": "See at what stage every campaign is stopped and who is in charge with one vote. You can change the person in charge right away, and the collaboration console below handles confirmation of conditions, inspection of submissions, and settlement reservations.",
  "모든 플랫폼의": "On all platforms",
  "모든 필수 항목을 입력해 주세요.": "Please enter all required fields.",
  "모든 협업을 한눈에 파악해 드려요. 대화 중인 업체 현황, 답장이 필요한 협업, 답장 초안은 물론 계약·정산·세금·광고 표시 같은 업무·법률 질문까지 물어보세요.": "We can see all collaborations at a glance. Ask about the status of the company you are talking to, collaborations that require a response, draft replies, and even business and legal questions such as contracts, settlement, tax, and advertising display.",
  "모든 협업을 함께 보고 업무를 도와드려요": "We see all collaborations together and help you with your work.",
