  "배송과 관련하여 셀러, 시청자(구매자), 배송업체, 금융기관 등 사이에 발생하는 분쟁은 당사자들 간의 해결을 원칙으로 하며, 회사는 고의 또는 중과실이 없는 한 책임을 지지 않습니다.": "Disputes that arise between sellers, viewers (buyers), delivery companies, financial institutions, etc. in relation to delivery are resolved between the parties, and the company is not responsible unless there is intent or gross negligence.",
