  "본 약관은 픽스폴리오(이하 \"회사\")가 제공하는 멀티링크 관리 및 라이브 커머스 솔루션 \"픽스폴리오(Picksfolio)\"(이하 \"서비스\")와 관련하여 회사, 유료 멤버십 회원(셀러), 시청자(구매자) 간의 권리, 의무 및 책임사항을 규정함을 목적으로 합니다.": "The purpose of these Terms and Conditions is to stipulate the rights, obligations and responsibilities between the Company, paid membership members (sellers), and viewers (buyers) in relation to the multi-link management and live commerce solution “Picksfolio” (hereinafter “Service”) provided by Picksfolio (hereinafter “Company”).",
  "본 페이지의 라이브 커머스 거래는 통신판매중개 플랫폼 픽스폴리오(Picksfolio)를 통해 이루어집니다.": "Live commerce transactions on this page are carried out through Picksfolio, a mail order brokerage platform.",
