  "생략": "Skipped",
  "서버 연결이 설정되지 않아 카카오 로그인을 사용할 수 없습니다. 아이디/비밀번호로 로그인해 주세요.": "Kakao Login cannot be used because the server connection has not been established. Please log in with your ID/password.",
