  "시간 경과에 의해 재판매가 곤란할 정도로 상품의 가치가 현저히 감소한 경우": "If the value of the product has decreased significantly over time to the point that resale is difficult.",
  "시간 도달 시 자동 차단": "Automatically block when time is reached",
  "시간 또는 일": "Hours or Days",
  "시간 한도에 도달한 유저는 다음 송출 시작 시 자동으로 차단됩니다(스트림 키 발급 거부). 별도 수동 차단 작업은 필요하지 않으며, 진행 중인 방송을 즉시 종료하려면 \"진행 중\" 탭에서 강제 종료를 사용하세요.": "Users who reach the time limit will be automatically blocked (stream key issuance denied) when the next broadcast begins. No separate manual blocking action is required. To immediately end an ongoing broadcast, use Force Stop in the “In Progress” tab.",
  "시작 희망일": "Target Start Date",
  "시작 희망일을 선택해주세요.": "Please select start date.",
  "시작일": "Start date",
