  "시작일을 고르면 마감일 차례로 넘어갑니다": "Once you select the start date, you will move through the due dates in order.",
  "시작하기": "Get started",
  "시점별 의견": "Opinions at each point in time",
  "시점은 00:12 처럼 적어 주세요.": "Please write the time point like 00:12.",
  "시청자": "Viewer",
  "시청자(구매자):": "Viewers (Buyers):",
  "시청자(구매자)가 라이브 방송을 통해 구매한 상품의 청약 철회, 교환, 반품, 환불 등은 전자상거래법 등 관련 법령 및 해당 멤버십 회원(셀러)이 고지한 판매 정책에 따라 처리됩니다.": "Withdrawal, exchange, return, refund, etc. of products purchased by viewers (buyers) through live broadcasts are processed in accordance with relevant laws and regulations such as the Electronic Commerce Act and the sales policy notified by the relevant membership member (seller).",
  "시청자(구매자)가 라이브 방송을 통해 상품을 주문·결제하는 경우, 주문 이행을 위해 다음과 같이 해당 방송의 멤버십 회원(셀러)에게 개인정보를 제공합니다.": "When a viewer (buyer) orders or pays for a product through a live broadcast, personal information is provided to the membership member (seller) of the broadcast as follows to fulfill the order.",
  "시청자(구매자)가 멤버십 회원(셀러)의 방송을 통해 상품을 구매하면서 결제대행사(PG)를 통해 결제한 금액을 의미합니다.": "This refers to the amount paid by a viewer (buyer) through a payment agency (PG) when purchasing a product through a broadcast by a membership member (seller).",
  "시청자(구매자)는 다음 각 호에 해당하는 경우 청약철회, 반품 또는 교환을 요청할 수 없습니다.": "Viewers (buyers) cannot request cancellation, return, or exchange in the following cases.",
  "시청자(구매자)는 상품 수령 후 7일 이내에 관련 법령에 따라 반품 또는 교환을 신청할 수 있으며, 라이브 방송 종료 이후 상품을 수령하기 전이라도 상품 불량이나 하자 사유가 명확한 경우에는 주문 취소를 요청할 수 있습니다.": "Viewers (buyers) may apply for return or exchange in accordance with relevant laws and regulations within 7 days of receiving the product, and if the reason for the product defect or defect is clear even before receiving the product after the end of the live broadcast, order cancellation can be requested.",
  "시청자(구매자)와 멤버십 회원(셀러) 간에 발생한 거래 관련 분쟁에 대하여 회사는 고의 또는 중과실이 없는 한 개입하거나 책임을 지지 않으며, 이러한 사실을 서비스 내 적절한 방법으로 고지합니다.": "The company does not intervene or take responsibility for transaction-related disputes that arise between viewers (buyers) and membership members (sellers) unless there is intent or gross negligence, and this fact is notified through an appropriate method within the service.",
  "시청자(구매자)의 사용 또는 일부 소비로 상품의 가치가 현저히 감소한 경우": "If the value of the product has decreased significantly due to use or partial consumption by viewers (buyers)",
  "시청자(구매자)의 상품 주문 접수, 결제 처리, 배송지 확인 및 판매자에게 주문 정보 제공": "Receiving product orders from viewers (buyers), processing payment, confirming delivery address, and providing order information to seller",
  "시청자(구매자)의 이용:": "Use by viewers (buyers):",
  "시청자(구매자)의 책임 있는 사유로 상품이 멸실·훼손된 경우": "If the product is lost or damaged due to reasons attributable to the viewer (buyer)",
  "시청자는 방송 중 장바구니에 담은 상품을 회사가 제공하는 일괄 결제 시스템을 통해 결제하며, 결제는 등록된 결제대행사(PG)를 통해 처리됩니다.": "Viewers pay for the products they put in their shopping cart during the broadcast through the lump sum payment system provided by the company, and the payment is processed through a registered payment agency (PG).",
  "시청자는 별도의 유료 구독 없이 멤버십 회원(셀러)의 방송을 시청하고 상품을 구매할 수 있으며, 이때 발생하는 비용은 구매한 상품 대금에 한합니다.": "Viewers can watch broadcasts and purchase products from membership members (sellers) without a separate paid subscription, and the cost incurred at this time is limited to the price of the purchased product.",
  "시행일: 2026년 4월 1일": "Enforcement date: April 1, 2026",
  "시행일: 2026년 9월 15일 (개정)": "Effective date: September 15, 2026 (amended)",
