  "실시간 라이브 방송 송출, 장바구니 담기·일괄 결제 등 커머스 특화 기능과 비즈니스 타임라인 등 멤버십 전용 기능을 이용하고자 하는 회원은 회사가 정한 유료 멤버십 정기 구독을 체결해야 합니다.": "Members who wish to use commerce-specific functions such as real-time live broadcasting, adding to cart, and bulk payment, and membership-only functions such as business timeline must sign a regular paid membership subscription determined by the company.",
