  "앱이 업데이트되었거나 네트워크가 불안정할 때 생길 수 있어요.": "This may occur when the app is updated or the network is unstable.",
  "약관 위반": "Violation of terms and conditions",
  "약관이 개정되는 경우 회사는 적용일자 및 개정사유를 명시하여 현행 약관과 함께 적용일자 7일 전부터(회원에게 불리한 내용으로 변경하는 경우에는 30일 전부터) 서비스 초기화면에 공지하며, 회원에게 불리한 변경의 경우 등록된 이메일 또는 서비스 내 알림으로 별도 통지합니다.": "If the terms and conditions are revised, the company will specify the date of application and the reason for revision and announce them on the initial screen of the service 7 days prior to the application date (30 days prior in case of changes that are unfavorable to members) along with the current terms and conditions. In case of changes that are unfavorable to members, a separate notification will be made via registered email or notification within the service.",
  "어두운 배경, 고급스러운 톤": "Dark background, luxurious tone",
