  "업로드된 게시물 주소를 인플루언서의 메타 계정 최근 게시물과 맞춰 조회수·반응을 가져옵니다. 인플루언서가 직접 적은 숫자는 성과 근거로 쓰지 않기 때문에, 연동 전 게시물은 집계 전으로 남습니다. 메타는 최근 게시물만 돌려주므로 오래된 캠페인의 게시물도 집계에서 빠질 수 있습니다.": "Retrieve the number of views and reactions by matching the uploaded post address with the influencer's meta account's most recent post. Since the numbers directly written by the influencer are not used as performance basis, posts before linking remain before aggregation. Meta only returns recent posts, so posts from older campaigns may also be left out of the count.",
