  "이 계정은 auth에는 있지만 프로필이 없습니다. 프로필 생성 전에는 멤버십 부여가 사용자 계정에 반영되지 않습니다.": "This account exists in auth but has no profile. Membership grants will not be reflected in your user account until you create a profile.",
