  "이 약관과 관련하여 당사자 간의 합의에 의해 추가로 작성된 계약서·협정서·통보서, 회사의 정책 변경, 관련 법령의 제·개정 또는 공공기관의 고시·지침 등에 따라 회사가 서비스를 통해 회원에게 공지하는 내용도 이 약관의 일부를 구성합니다.": "In relation to these Terms and Conditions, additional contracts, agreements and notices drawn up by agreement between the parties, changes in the Company's policies, enactment or amendment of related laws, or notices or guidelines of public institutions, etc., and contents notified by the Company to members through the Service also form part of these Terms and Conditions.",
  "이 약관에 따라 회사가 회원에게 통지하는 경우 서비스 내 공지사항 게시, 회원이 등록한 이메일, 앱 푸시 알림, 서비스 내 메시지 등의 방법을 사용할 수 있으며, 통지가 회원의 등록된 접속정보에 도달한 시점에 통지 효력이 발생한 것으로 봅니다.": "When the company notifies a member in accordance with these terms and conditions, methods such as posting a notice within the service, email registered by the member, app push notification, or messaging within the service may be used. The notice is deemed to have taken effect when the notice reaches the member's registered access information.",
  "이 약관에 명시되지 아니한 사항은 「전자상거래 등에서의 소비자보호에 관한 법률」, 「약관의 규제에 관한 법률」, 「정보통신망 이용촉진 및 정보보호 등에 관한 법률」, 공정거래위원회가 정하는 「전자상거래 등에서의 소비자보호지침」 및 기타 관계 법령 또는 상관례에 따릅니다.": "Matters not specified in these terms and conditions shall be subject to the 「Act on Consumer Protection in Electronic Commerce, etc.」, 「Act on Regulation of Terms and Conditions」, 「Act on Promotion of Information and Communications Network Utilization and Information Protection, etc.」, 「Consumer Protection Guidelines in Electronic Commerce, etc.」 established by the Fair Trade Commission and other related laws and regulations or commercial practices.",
  "이 약관의 일부 조항이 관련 법령에 의해 무효 또는 집행 불가능한 것으로 판단되더라도 나머지 조항의 효력에는 영향을 미치지 않습니다.": "Even if some provisions of these Terms and Conditions are determined to be invalid or unenforceable under applicable laws, this will not affect the validity of the remaining provisions.",
  "이 약관의 해석 및 회사와 회원 간의 분쟁에 대해서는 대한민국 법령을 준거법으로 합니다.": "The laws of the Republic of Korea shall govern the interpretation of these terms and conditions and disputes between the company and members.",
  "이 이름이 유저네임이 되고 채팅에 표시됩니다.": "This name will become your username and will appear in chat.",
