  "이 채널은 담당자와 1:1입니다. 브랜드는 이 대화를 볼 수 없고, 전달이 필요한 내용은 담당자가 정리해 옮깁니다.": "This channel is 1:1 with the person in charge. The brand cannot see this conversation, and the content that needs to be conveyed is organized and transferred by the person in charge.",
  "이 채널은 담당자와 1:1입니다. 인플루언서는 이 대화를 볼 수 없고, 수정 요청이나 의견은 담당자가 정리해 전달합니다.": "This channel is 1:1 with the person in charge. Influencers cannot see this conversation, and requests for corrections or comments are organized and delivered by the person in charge.",
