  "인플루언서에게 제안을 보내면 여기서 현황을 확인할 수 있습니다.": "Send a proposal to an influencer and you can check the status here.",
  "인플루언서와 브랜드는 서로의 방을 볼 수 없습니다. 양쪽 말을 옮기는 것은 담당자입니다.": "Influencers and brands cannot see each other’s rooms. It is the person in charge of moving both pieces.",
