  "천재지변 등 불가항력적 사유가 발생한 경우 해당 기간은 배송 소요 기간에서 제외됩니다.": "If force majeure, such as a natural disaster, occurs, that period is excluded from the delivery period.",
  "천재지변, 국가 비상사태, 해결이 곤란한 기술적 결함, 기간통신사업자의 서비스 중지 등 불가항력적 사유로 서비스를 제공할 수 없는 경우 회사는 서비스 제공을 제한하거나 중단할 수 있으며, 이로 인해 회원 또는 제3자가 입은 손해에 대해서는 고의 또는 중과실이 없는 한 책임을 지지 않습니다.": "If the service cannot be provided due to force majeure, such as natural disasters, national emergencies, technical defects that are difficult to resolve, or service interruption by key telecommunications carriers, the company may limit or suspend the provision of the service, and will not be liable for any damage suffered by members or third parties as a result, unless there is intent or gross negligence.",
