  "취소 중...": "Cancelling...",
  "취소·반품·교환에 소요되는 배송비는 귀책 사유가 있는 자가 부담함을 원칙으로 합니다(단순 변심은 구매자 부담, 상품 하자는 셀러 부담).": "In principle, shipping costs for cancellation, return, and exchange are borne by the person at fault (buyer is responsible for simple change of mind, seller is responsible for defective product).",
