  "카드": "Card",
  "카드 결제 건의 취소 또는 환불 요청 시 결제된 카드로 카드매출 취소 요청되며, 카드사 처리 기준에 따라 영업일 2~5일 이내 카드결제 취소 처리됩니다.": "When canceling a card payment or requesting a refund, cancellation of card sales will be requested using the card used for payment, and the card payment will be canceled within 2 to 5 business days according to the card company's processing standards.",
  "카드 결제 후 취소 또는 환불 요청 시 결제된 카드로 카드매출 취소 요청되며, 카드사 처리 기준에 따라 영업일 2~5일 이내 카드결제 취소 처리됩니다.": "When canceling or requesting a refund after making a card payment, card sales will be canceled using the card used for payment, and the card payment will be canceled within 2 to 5 business days depending on the card company's processing standards.",
