  "콘텐츠 가이드라인 작성하기": "Write content guidelines",
  "콘텐츠 검수": "Content Inspection",
  "콘텐츠 기능이 필요하면 스탠다드, 협업 AI까지 더하려면 AI 협업, 디엠 자동화를 포함해 모든 기능을 쓰려면 프로 플랜을 선택하세요. 모든 플랜은 월 단위 구독이며 언제든 해지할 수 있고, 표시된 금액은 모두 부가세(VAT) 포함입니다.": "Choose Standard for content features, AI Collaboration to add AI tools, or Pro Plan for all features including DM automation. All plans are monthly subscriptions and include VAT.",
  "콘텐츠 기획 AI": "Content Planning AI",
  "콘텐츠 마감": "Content deadline",
  "콘텐츠 성격에 따라 가장 효과적인 레이아웃을 선택하세요.": "Choose the most effective layout for your content.",
  "콘텐츠 추가": "Add Content",
