  "픽스폴리오 담당자": "Pixfolio Manager",
  "픽스폴리오 협업": "Picksfolio collaboration",
  "픽스폴리오 담당자가 브랜드와 조건을 정리해 보낸 제안입니다. 조건을 확인하고 진행 여부만 알려주시면 됩니다.": "This is a proposal sent by the person in charge of Pixfolio, summarizing the brand and conditions. All you have to do is check the conditions and let us know if you want to proceed.",
  "픽스폴리오 담당자가 캠페인에 맞는 인플루언서를 찾아 올린 조합입니다. 함께하고 싶은 분을 리스트에 담아 주시면 담당자가 일정·가이드·단가를 들고 직접 제안합니다.": "This is a combination posted by Pixfolio staff after finding influencers that fit the campaign. If you list the people you would like to join, the person in charge will personally make a proposal with a schedule, guide, and unit price.",
  "픽스폴리오 멤버십은 세 가지 플랜으로 운영됩니다. 스탠다드 멤버십(영상 업로드 · 콘텐츠 업로드)은 월 4,900원(VAT 포함), AI 협업 멤버십(스탠다드 혜택 + 협업 AI)은 월 6,900원(VAT 포함), 프로 플랜(스탠다드 · AI 협업 혜택 + 인스타그램 디엠 자동화)은 월 18,700원(VAT 포함)이며, 회사의 정책 변경 시 사전 공지 후 조정될 수 있습니다. 표시된 모든 금액은 부가가치세가 포함된 금액입니다. 비즈니스 수신함과 협업 타임라인은 모든 이용자에게 무료로 제공됩니다.": "Pixfolio membership operates in three plans. Standard membership (video upload / content upload) is 4,900 won per month (VAT included), AI collaboration membership (standard benefits + collaboration AI) is 6,900 won per month (VAT included), and Pro plan (standard / AI collaboration benefits + Instagram DM automation) is 18,700 won per month (VAT included). If the company's policy changes, it may be adjusted after prior notice. All prices shown are inclusive of VAT. Business Inbox and Collaboration Timeline are free for all users.",
  "픽스폴리오 서비스:": "Pixfolio Service:",
  "픽스폴리오(이하 \"회사\")는 회원의 개인정보보호를 매우 중요시하며, 이용자가 회사의 서비스(이하 \"서비스\")를 이용함과 동시에 온라인상에서 회사에 제공한 개인정보가 보호 받을 수 있도록 최선을 다하고 있습니다. 이에 회사는 개인정보보호법 등 관련 법규를 준수하고 있습니다.": "Pixfolio (hereinafter referred to as “Company”) attaches great importance to the protection of members’ personal information, and does its best to ensure that personal information provided to the Company online while users use the Company’s services (hereinafter referred to as “Services”) is protected. Accordingly, the company complies with relevant laws and regulations, including the Personal Information Protection Act.",
  "픽스폴리오(Picksfolio)": "Picksfolio",
  "픽스폴리오(Picksfolio) 개인정보처리방침": "Picksfolio Privacy Policy",
  "픽스폴리오(Picksfolio) 서비스 이용약관": "Picksfolio Service Terms of Use",
  "픽스폴리오는 통신판매중개자로서 라이브 커머스 시스템과 결제·정산 수단만을 제공하며, 방송을 통해 판매되는 상품의 등록·품질·배송·교환·환불 등 거래 이행에 관한 모든 책임은 판매 주체인 멤버십 회원(셀러)에게 있습니다.": "Pixfolio, as a mail order intermediary, provides only a live commerce system and payment/settlement methods, and all responsibility for transaction performance, including registration, quality, delivery, exchange, and refund of products sold through broadcasts, lies with the membership member (seller) who is the seller.",
  "픽스폴리오에 다시 오신 것을 환영합니다.": "Welcome back to PICKSFOLIO.",
  "픽스폴리오에 등록된 인플루언서": "Influencers registered in PIXfolio",
  "픽스폴리오에 등록된 인플루언서를 한 표로 정리해 둡니다. 인플루언서가 브랜드 매칭 등록에서 직접 고른 분야로 추린 뒤, 팔로워 많은 순과 인사이트 좋은 순으로 나란히 볼 수 있습니다. 인사이트는 조회율·반응률·최근 릴스 동향을 합친 점수로, 팔로워 규모와 무관하게 콘텐츠 성과만 봅니다.": "The influencers registered in Pixfolio are organized into one table. After selecting the field that the influencer directly selected through brand matching registration, you can view them side by side in order of the most followers and the best insights. Insight is a score that combines view rate, response rate, and recent release trends, and only looks at content performance regardless of follower size.",
  "픽스폴리오와 함께 나만의 포트폴리오를 만들어보세요": "Start building your portfolio with PICKSFOLIO",
