  "협업 타임라인 AI는 기본적으로 제미나이(무료, AI 멤버십 포함)로 동작합니다. 깊은 분석이나 문서·계약서 검토처럼 더 강력한 답변이 필요할 때는": "Collaborative Timeline AI basically operates as Gemini (free, includes AI membership). When you need a more powerful answer, such as in-depth analysis or document or contract review",
