  "환불 반영 −": "Refund reflected −",
  "환불은 취소·반품·교환 사유 및 배송비 부담 주체가 확인된 후 5영업일 이내에 결제 수단에 따라 처리됨을 원칙으로 하며, 정산이 완료된 판매 대금에 대해서는 셀러와의 정산 조정을 거쳐 환불이 이루어집니다.": "In principle, refunds are processed according to the payment method within 5 business days after the reason for cancellation, return, or exchange and the person responsible for shipping costs are confirmed. For sales proceeds that have been settled, refunds are made after settlement adjustment with the seller.",
  "환영합니다!": "Welcome!",
  "활동 완료 시 확정 지급": "Guaranteed payout upon completion",
  "활성": "Active",
