  "AI 협업 멤버십(6,900원) 이상(프로 18,700원 포함)을 구독하면 협업 대화 요약, 일정 정리, 답장 초안 작성을 바로 이용할 수 있어요. 비즈니스 계정과 일반 계정 모두 동일한 멤버십으로 사용할 수 있습니다. (모든 금액 부가세 포함)": "If you subscribe to AI Collaboration Membership (KRW 6,900) or higher (including Pro KRW 18,700), you can immediately use collaboration conversation summarization, schedule organization, and reply drafting. Both business and standard accounts can be used with the same membership. (All prices include VAT)",
