  "메타 광고 집행 권한 심사 전이라 실제 노출은 아직 시작되지 않습니다. 광고 현황에 '요청' 상태로 올라가고, 심사가 끝나면 이 요청이 그대로 집행됩니다.": "Meta ad delivery permission is still under review, so real impressions have not started yet. It will appear in Ad Status as 'Requested', and once the review is done this request will run as-is.",
