  "인스타그램 프로필 열기": "Open Instagram profile",
  "담당자가 조건 정리 중": "The person in charge is preparing the terms",
  "조건 · 일정 · 정산은 담당자가 정리합니다. 브랜드 의견은 단계별 피드백으로 들어옵니다.": "The person in charge handles the terms, schedule and settlement. Brand comments come in as stage-by-stage feedback.",
  "기획안 · 영상 피드백은 인플루언서에게 바로 전달됩니다. 조건 · 일정 · 정산 문의는 담당자에게 남겨 주세요.": "Content plan and video feedback goes straight to the influencer. For questions about terms, schedule or settlement, leave a note for the person in charge.",
  "진행 중 인플루언서": "Influencers in progress",
