  "진행을 확정하면 아래 보드의 제품 배송 칸에 카드가 한 장씩 들어옵니다.": "Once you confirm, a card enters the Product shipping column of the board below one by one.",
  "담당자가 진행을 확정하면 아래 보드의 제품 배송 칸에 카드가 한 장씩 들어옵니다.": "Once the person in charge confirms, a card enters the Product shipping column of the board below one by one.",
