  "인스타그램에서 받은 태그된 미디어 목록과, 우리 서비스에 연동된 인플루언서의 최근 콘텐츠를 합쳐 보여줍니다.": "Combines the tagged media list received from Instagram with recent content from influencers linked to our service.",
  "조회수는 목록을 불러올 때 콘텐츠를 올린 계정의 인스타그램 인사이트에서 함께 받아옵니다. 그래서 올린 계정이 우리 서비스에 연동돼 있어야 값을 물어볼 수 있고, 올린 직후라 아직 집계되지 않은 콘텐츠는 값이 비어 있습니다.": "View counts are fetched together with the list from the Instagram insights of the account that posted the content. So the posting account has to be linked to our service for the value to be requested, and content posted just now that has not been tallied yet comes back empty.",
  "이번 조회에서 조회수가 비어 있던": "Of the content whose views were empty in this fetch,",
  "개 중": "of",
