  "나머지는 인스타그램이 아직 조회수를 집계하지 않았거나, 연동 계정에 인사이트 권한이 없는 콘텐츠입니다.": "The rest is content Instagram has not tallied views for yet, or content whose linked account lacks insights permission.",
  "도달·저장수는 다른 계정이 올린 게시물이라 조회할 수 없어 표시하지 않습니다.": "Reach and saves cannot be looked up for posts made by other accounts, so they are not shown.",
  "가이드 보고 기획안": "Content plan from the guide",
  "브랜드에서 준 기본 가이드를 보고 이번 협업 콘텐츠 기획안을 작성해 주세요.": "Read the basic guide from the brand and write the content plan for this collab.",
  "가이드에서 꼭 지켜야 할 것부터 정리하고, 컷 구성과 캡션 초안까지 잡아 주세요.": "Start with the must-follow points from the guide, then lay out the shot list and a caption draft.",
  "가이드가 없으면 지금까지 나온 내용으로 먼저 초안을 잡고 필요한 것만 물어봐 주세요.": "If there is no guide, draft from what has come up so far and only ask about what you need.",
  "인스타 광고 캡션 초안": "Instagram ad caption draft",
  "협업 제품으로 올릴 인스타그램 광고 캡션 초안을 톤이 다른 3가지 버전으로 써 주세요.": "Write an Instagram ad caption draft for the collab product in three versions with different tones.",
  "해시태그와 광고 표시 문구도 함께 넣어 주세요.": "Include hashtags and the ad disclosure wording as well.",
  "협업 제품으로 찍을 숏폼(릴스) 촬영 가이드를 써 주세요. 컷 번호를 붙이고 각 컷마다": "Write a short-form (Reels) shooting guide for the collab product. Number the shots and, for each one,",
  "영상(장면 설명)과 자막(화면에 올릴 문구)을 나눠서 마지막 CTA까지 정리해 주세요.": "split it into video (scene description) and captions (on-screen text), all the way to the final CTA.",
  "어떤 무드로 갈지도 함께 제안해 주세요.": "Suggest which mood to go for as well.",
  "담당자에게 보낼 메시지": "Message to the person in charge",
  "픽스폴리오 담당자에게 보낼 메시지 초안을 써 주세요. 지금 진행 상황에 맞게 쓰고,": "Write a draft message to send to the PICKSfolio person in charge. Write it to match where things stand now,",
  "함께 물어보면 좋을 내용도 정리해 주세요.": "and list what would be worth asking about as well.",
  "협업 전 확인할 것": "What to check before the collab",
  "이 협업을 진행하기 전에 확인해야 할 항목을 정리해 주세요. (마감일, 2차 활용 범위,": "List what needs checking before running this collab. (deadline, secondary usage scope,",
  "필수 문구, 수정 횟수, 정산 시점·방식 등)": "required wording, number of revisions, settlement timing and method, and so on)",
  "내 협업 현황": "My collab status",
  "지금 대화 중인 업체와 협업 현황을 정리해 주세요. 답장이 필요한 곳부터 알려 주세요.": "Summarize the status of the collabs with the companies you are talking to now. Start with the ones that need a reply.",
  "첨부한 브랜드 가이드를 읽고, 이 협업으로 만들 콘텐츠 기획안을 작성해 주세요.": "Read the attached brand guide and write the content plan for the work this collab will produce.",
  "이 대화": "this conversation",
  "대화 내용은 상대방에게 그대로 남습니다. 상대가 새 메시지를 보내면 다시 나타납니다.": "The conversation stays exactly as it is for the other side. If they send a new message, it reappears.",
