  "이 대화를 비우고 새로 시작": "Clear this conversation and start over",
  "새 대화": "New conversation",
  "AI 멤버십에 가입하면 브랜드 가이드를 읽고 쓰는 콘텐츠 기획안, 인스타 광고 캡션·숏폼 대본 초안, 담당자에게 보낼 메시지 초안, 협업 대화 요약과 일정 정리를 이용할 수 있어요. 멤버십 가입은 PICKS Folio 웹사이트에서 할 수 있으며, 웹에서 가입하면 앱에서도 그대로 사용됩니다.": "With an AI membership you get content plans written from the brand guide, Instagram ad caption and short-form script drafts, message drafts for the person in charge, and collab conversation summaries and schedule roundups. You can join a membership on the PICKS Folio website, and joining on the web works in the app too.",
  "AI 협업 멤버십(6,900원) 이상(프로 18,700원 포함)을 구독하면 브랜드 가이드를 읽고 쓰는 콘텐츠 기획안, 인스타 광고 캡션·숏폼 대본 초안, 담당자에게 보낼 메시지 초안, 협업 대화 요약과 일정 정리를 바로 이용할 수 있어요. 비즈니스 계정과 일반 계정 모두 동일한 멤버십으로 사용할 수 있습니다. (모든 금액 부가세 포함)": "Subscribe to the AI Collaboration membership (₩6,900) or above (including Pro at ₩18,700) and you can immediately use content plans written from the brand guide, Instagram ad caption and short-form script drafts, message drafts for the person in charge, and collab conversation summaries and schedule roundups. Business and regular accounts both use the same membership. (all prices include VAT)",
