  "를 말해 주시면 그 톤으로 다시 잡아 드립니다. 계약·정산·세금·광고 표시 같은 업무 질문도 물어보세요.": "you want, it is rewritten in that tone. Feel free to ask work questions about contracts, settlement, taxes or ad disclosure too.",
  "브랜드 가이드 첨부 (이미지 · PDF, 최대 3개)": "Attach brand guide (image · PDF, up to 3)",
  "브랜드 가이드를 첨부하면 기획안을 써 드려요. 캡션·숏폼 대본·담당자 메시지도 요청해 보세요.": "Attach the brand guide and a content plan is written for you. Try asking for captions, short-form scripts or a message to the person in charge too.",
  "클로드 플랜과 크레딧 충전은 네이버페이, 페이코, 카카오페이 등 간편결제를 지원하지 않습니다.": "Claude plans and credit top-ups do not support easy-pay methods such as Naver Pay, PAYCO or Kakao Pay.",
