  "채널을 보고 매칭": "Matched on the channel",
  "담당자가 채널 성격과 시청자, 단가를 확인한 뒤 맞는 브랜드를 골라 연결합니다.": "The person in charge reviews the channel's character, its audience and its rate, then picks and connects a matching brand.",
  "담당자 배정": "Person in charge assigned",
  "광고비와 업무 범위, 일정이 적힌 제안이 도착합니다. 수락할지만 정하면 됩니다.": "An offer arrives with the ad fee, scope of work and schedule. All you decide is whether to accept.",
