  "담당자가 조율": "Coordinated by the person in charge",
  "가입하고 채널을 연결하면 담당자가 채널을 확인합니다.": "Sign up and connect your channel, and the person in charge reviews it.",
  "담당자가 채널에 맞는 브랜드 광고를 찾아 제안합니다.": "The person in charge finds brand ads that fit your channel and sends offers.",
  "조건 협의": "Terms negotiated",
  "광고비와 업무 범위, 일정을 담당자가 브랜드와 정리합니다.": "The person in charge settles the ad fee, scope of work and schedule with the brand.",
  "진행·정산": "Delivery and settlement",
  "단계별 진행과 정산 일정이 대시보드에서 그대로 이어집니다.": "Stage-by-stage progress and the settlement schedule carry straight through on your dashboard.",
  "담당자가 브랜드 광고를": "Your person in charge brings you",
  "직접 제안합니다": "brand ads directly",
  "채널마다 담당자가 배정됩니다. 담당자가 맞는 브랜드를 찾아 광고비와 업무 범위까지 정리해 제안하고, 협의부터 진행 관리와 정산까지 함께 챙깁니다.": "Every channel gets a person in charge. They find matching brands, put together the ad fee and scope of work, and stay with you from negotiation through delivery and settlement.",
