  "계정이 연동되었습니다. 팔로워·릴스 조회수를 불러오는 중입니다.": "Your account is connected. Fetching followers and Reels views.",
  "최신 정보를 불러왔어요. 릴스 조회수가 비어 있으면 계정을 다시 연동해 조회수 권한을 허용해 주세요.": "The latest information has been loaded. If Reels views are empty, reconnect the account and allow the views permission.",
  "인스타그램 계정 연동을 해제할까요? 지금까지 확인된 팔로워·조회수는 그대로 남지만, 해제 후에는 자동으로 갱신되지 않습니다. 언제든 다시 연동할 수 있어요.": "Disconnect your Instagram account? The followers and views confirmed so far stay as they are, but they will not refresh automatically after disconnecting. You can reconnect any time.",
  "인스타그램 연동이 해제되었습니다. 필요하면 언제든 다시 연동할 수 있어요.": "Instagram has been disconnected. You can reconnect any time you need to.",
  "카카오톡 아이디를 입력해 주세요. 담당자가 카톡으로 제안을 보냅니다.": "Please enter your KakaoTalk ID. The person in charge sends offers over KakaoTalk.",
