  "연동한 계정": "Connected account",
  "· 다시 연동이 필요해요": "· needs reconnecting",
  "인스타그램 동의 기간이 끝났습니다. 계정과 등록 정보는 그대로 있으니 다시 연동만 해 주시면 팔로워·릴스 조회수가 최신으로 채워집니다.": "The Instagram consent period has ended. Your account and registration details are untouched, so just reconnect and followers and Reels views fill in with the latest figures.",
  "다시 연동하기": "Reconnect",
  "해제하는 중...": "Disconnecting...",
  "연동 해제하기": "Disconnect",
  "릴스 조회수를 아직 받지 못했습니다. \"새로 불러오기\"를 눌러도 비어 있으면 계정을 다시 연동해 조회수(인사이트) 권한을 허용해 주세요. 팔로워 수는 정상적으로 확인되었습니다.": "Reels views have not come back yet. If it is still empty after pressing \"Reload\", reconnect the account and allow the views (insights) permission. Your follower count was confirmed normally.",
  "다른 계정으로 바꾸려면 해제 후 다시 연동해 주세요.": "To switch to a different account, disconnect and connect again.",
  "해제 중": "Disconnecting",
  "검토 중": "Under review",
  "브랜드와 담당자가 지원 내용을 확인하고 있습니다.": "The brand and the person in charge are reviewing your application.",
  "선정 · 진행 준비": "Selected · getting ready",
  "미선정": "Not selected",
  "다른 캠페인에서 다시 만나요.": "See you on another campaign.",
  "오늘까지": "Due today",
  "인스타그램 연동에 실패했습니다. 다시 시도해 주세요.": "Connecting Instagram failed. Please try again.",
  "인스타그램 계정을 연동해 주세요": "Please connect your Instagram account",
  "협업 캠페인은 연동한 계정으로 진행합니다. 진행하던 협업은 그대로 보관되어 있어, 다시 연동하면 바로 이어서 볼 수 있어요.": "Collab campaigns run on the connected account. Collabs already in progress are kept as they are, so reconnecting brings you right back to them.",
  "연동 창을 여는 중": "Opening the connection window",
  "인스타그램 연동하기": "Connect Instagram",
  "진행 요청": "Action needed",
  "현재 단계": "Current stage",
  "확정 대기": "Awaiting",
  "조건 · 일정 문의는 담당자에게 보내 주세요.": "For questions about terms or the schedule, message the person in charge.",
  "진행 중인 캠페인을 눌러 단계 · 인사이트 · 정산을 확인하고 입력하세요": "Tap a running campaign to check and fill in stages, insights and settlement",
