  "공동구매 오픈챗": "Group buy open chat",
  "팔레트를 열어 원하는 색을 직접 조정할 수 있어요. 글자 색은 자동으로 맞춰집니다": "Open the palette and tune any color you like. Text color adjusts automatically",
