  "상품명 검색바 위의 버튼 줄입니다. 배경색과 글자색을 따로 고를 수 있어요": "The row of buttons above the product search bar. You can pick the background and text color separately",
  "아직 카테고리가 없어 예시 이름으로 보여드려요. 카테고리를 만들면 내 페이지의 실제 버튼으로 바뀝니다": "There are no categories yet, so example names are shown. Create a category and these turn into the real buttons on your page",
  "선택된 버튼 배경": "Selected button background",
  "선택된 버튼 글자": "Selected button text",
