  "· 본문 미작성": "· no caption yet",
  "브랜드가 진행사항에 올린 가이드 파일이 아직 없어요. 기획안은 그 파일을 근거로 쓰기 때문에, 담당자에게 가이드 파일을 요청하시거나 아래 📎 로 직접 첨부해 주세요.": "The brand has not uploaded a guide file under progress yet. The content plan is written from that file, so ask the person in charge for the guide file or attach it yourself with 📎 below.",
  "참고 파일 첨부 (이미지 · PDF, 최대 3개)": "Attach reference files (image · PDF, up to 3)",
  "기획안이나 본문을 부탁하거나, 수정해 달라고 해 보세요.": "Ask for a content plan or a caption, or ask for a revision.",
  "초안은 카드에서 직접 고칠 수 있고, 반영 버튼을 누르기 전에는 저장되지 않아요. 조건 · 일정 · 정산 문의는 담당자에게 확인해 주세요.": "Drafts can be edited right on the card and nothing is saved until you press Apply. For questions about terms, schedule or settlement, check with the person in charge.",
  "가이드라인 파일을 올리거나 내용을 적어 주세요.": "Please upload a guideline file or write out the content.",
  "콘텐츠 가이드라인 올리기": "Upload content guidelines",
  "가이드라인 올리기": "Upload guidelines",
  "가지고 계신 가이드 파일을 그대로 올려 주세요. 파일이 여러 개여도 됩니다.": "Just upload the guide file you already have. Several files are fine.",
  "가이드라인 파일": "Guideline files",
