  "인플루언서가 확정되고 업로드가 끝나면 이곳에 성과가 쌓입니다.": "Once influencers are confirmed and uploading is done, performance accumulates here.",
  "업로드한 게시물의 성과를 받아오려면 캠페인용 인스타그램 계정 연동이 필요합니다.": "To receive the performance of uploaded posts, the campaign's Instagram account has to be connected.",
  "조회수는 인사이트 권한이 없어 비어 있고, 단가는 반응 기준으로 계산했습니다.": "Views are empty because there is no insights permission, so the unit cost was calculated on engagement.",
