  "피드백 보내기": "Send feedback",
  "장면마다 적은 피드백과 전체 피드백을 한 번에 저장합니다. 저장하면 인플루언서에게 바로 전달되고, 각 피드백은 적어 둔 장면 아래에 그대로 붙습니다.": "Saves the per-scene feedback and the overall feedback in one go. Once saved it goes straight to the influencer, and each piece of feedback sits right under the scene you wrote it on.",
