  "발송 완료": "Mark as shipped",
  "장면 하나에 설명 · 자막 · 나레이션을 적고, 아래 + 로 다음 장면을 추가하세요. 자막과 나레이션은 없으면 비워 두셔도 됩니다. 브랜드는 장면마다 피드백을 답니다.": "Write the description, captions and narration for one scene, then add the next scene with the + below. Captions and narration can be left empty if there are none. The brand leaves feedback on each scene.",
  "어떤 장면을 찍는지 (예: 제품을 손에 들고 카메라 정면)": "What the shot is (e.g. holding the product, facing the camera)",
