  "해시태그와 광고 표기(#광고 · 유료광고 포함)까지 함께 적어 주세요. 브랜드가 이 글에도 피드백을 남깁니다.": "Include the hashtags and the ad disclosure (#ad, paid partnership and so on) as well. The brand leaves feedback on this text too.",
