  "지금 올라간 안 ·": "Current version ·",
  "번째 ·": "·",
  "초안 영상": "Draft video",
  "초안 영상 열기": "Open the draft video",
  "자 함께 제출": "characters submitted together",
  "본문 캡션이 아직 비어 있습니다 · 위 칸에 적어 저장해 주세요": "The caption is still empty · please write it in the field above and save",
  "인스타 본문 캡션 · 이 글이 영상 아래에 게시됩니다": "Instagram caption · this text is posted under the video",
  "본문 캡션이 비어 있습니다. 아래 칸으로 본문도 함께 요청해 주세요 — 검토하지 않으면 업로드 당일에 처음 보게 됩니다.": "The caption is empty. Ask for the caption in the field below as well — if you do not review it, you see it for the first time on upload day.",
  "인플루언서가 초안 영상과 본문 캡션을 올리면 여기에 표시됩니다.": "Once the influencer uploads the draft video and caption, they appear here.",
  "수정이 필요한 장면과 이유를 적어 주세요.": "Please write which scene needs revising and why.",
  "본문 캡션 피드백": "Caption feedback",
  "본문 캡션에 남기는 피드백": "Feedback left on the caption",
  "고쳤으면 하는 문장과 이유를 적어 주세요. (예: 첫 줄에 제품명이 들어가야 합니다 / #광고 표기를 맨 앞으로)": "Write the sentences you want changed and why. (e.g. the product name has to be in the first line / move the #ad disclosure to the front)",
  "본문 캡션이 먼저 올라왔습니다. 초안 영상이 올라오면 영상과 본문을 함께 검토할 수 있어요.": "The caption came in first. Once the draft video is up, you can review the video and caption together.",
  "본문 캡션은 저장됐습니다. 초안 영상을 올리면 브랜드가 영상과 본문을 함께 검토합니다.": "The caption has been saved. Upload the draft video and the brand reviews the video and the caption together.",
  "검토를 완료하면 이 영상과 본문 캡션이 그대로 게시됩니다. 두 가지를 모두 확인한 뒤 눌러 주세요.": "Once you finish the review, this video and caption are posted exactly as they are. Please press this after checking both.",
  "영상 검토 완료": "Video review done",
  "영상 검토 완료 · 담당자와 소통 후 업로드 일정을 정하세요": "Video review done · talk with the person in charge and set the upload date",
  "검토를 마친 영상과 본문 캡션은 이대로 확정입니다. 언제 올릴지는 담당자와 이야기해 정한 뒤 게시해 주세요. 올린 뒤 업로드 단계에 게시물 링크와 광고 파트너십 코드를 남기면 끝입니다.": "The reviewed video and caption are final as they are. Talk with the person in charge about when to post, then publish. After posting, leave the post link and the ad partnership code at the upload stage and you are done.",
  "검토 완료된 본문 캡션 · 이대로 붙여넣어 주세요": "Reviewed caption · please paste it exactly as it is",
  "픽스폴리오 정산 예정": "PICKSfolio settlement due",
  "이 협업 정산금": "Settlement for this collab",
  "픽스폴리오가 입금을 확인했습니다. 인플루언서 지급과 원천징수는 픽스폴리오가 진행합니다.": "PICKSfolio has confirmed the deposit. PICKSfolio handles the influencer payouts and withholding tax.",
  "정산은 픽스폴리오에 한 번 보내면 됩니다. 캠페인 정산 탭에서 보낼 금액을 확인해 주세요.": "For settlement you send one transfer to PICKSfolio. Check the amount to send in the Campaign settlement tab.",
  "서류 제출 완료 · 담당자가 지급일을 정하는 중": "Documents submitted · the person in charge is setting the payout date",
