  "예: 국민은행": "e.g. KB Kookmin Bank",
  "신분증과 같은 이름": "The same name as on the ID",
  "계좌번호": "Account number",
  "- 없이 입력해도 됩니다": "You can enter it without dashes",
  "예금주가 신분증의 이름과 다르면 은행에서 반송됩니다. 제출한 서류는 담당자만 열어 볼 수 있고 브랜드에게는 제출 여부만 표시됩니다.": "If the account holder's name differs from the name on the ID, the bank returns it. Only the person in charge can open the documents you submit; the brand only sees whether they were submitted.",
  "정산 서류 다시 제출": "Submit the settlement documents again",
  "정산 서류 제출": "Submit the settlement documents",
  "제출": "Submit",
  "· 미확인": "· not checked",
  "저장하면 인플루언서 정산금 화면의 지급 예정일과 협업 현황 캘린더에 그대로 올라갑니다.": "Save it and it goes straight onto the expected payout date on the influencer's settlement screen and the collab status calendar.",
  "브랜드 입금 확인 전입니다": "The brand's deposit has not been confirmed yet",
  "브랜드가 픽스폴리오에 보낸 일괄 정산금을 캠페인 정산 탭에서 먼저 확인해 주세요. 확인하면 지급 완료 처리가 열립니다.": "Please confirm the bulk settlement the brand sent to PICKSfolio in the Campaign settlement tab first. Once confirmed, marking it as paid opens up.",
  "아직 업로드 전": "Not uploaded yet",
  "브랜드 검토 완료 · 담당자와 소통 후 업로드 일정을 정하세요": "Brand review done · talk with the person in charge and set the upload date",
  "검토를 마친 초안 영상과 본문 캡션을 그대로 올리시면 됩니다. 올리는 날짜는 담당자와 맞춰 주세요. 올린 뒤 아래에 게시물 링크와 광고 파트너십 코드를 남겨 주세요.": "Just post the draft video and caption you had reviewed, exactly as they are. Line up the posting date with the person in charge. After posting, leave the post link and the ad partnership code below.",
