  "캠페인 담당자 이름을 입력해 주세요.": "Please enter the campaign contact's name.",
  "캠페인 담당자 연락처를 입력해 주세요.": "Please enter the campaign contact's phone number.",
  "담당자 연락처를 끝까지 입력해 주세요.": "Please enter the full contact phone number.",
  "캠페인 담당자 이메일을 입력해 주세요.": "Please enter the campaign contact's email.",
  "담당자 이메일 주소를 다시 확인해 주세요.": "Please check the contact's email address again.",
  "콘텐츠 형식을 골라 주세요.": "Please pick the content format.",
  "메가 한 명으로 화제를 만들고 마이크로·나노로 후속 반응을 채우는 구성이 가장 흔합니다. 배분액은 각 규모 금액 구간의 시작값으로 계산하고, 실제 금액은 담당자가 후보를 확정할 때 그 구간 안에서 정해집니다.": "The most common setup is one mega influencer to create the buzz, with micro and nano influencers filling in the follow-up. The allocation is calculated from the starting value of each tier's amount range, and the actual amount is set within that range when the person in charge confirms the candidates.",
  "캠페인 담당자 *": "Campaign contact *",
  "지난 캠페인과 동일": "Same as the last campaign",
  "담당자 이름 *": "Contact name *",
  "김담당": "Jane Kim",
  "담당자 이메일 *": "Contact email *",
  "계약서 · 세금계산서 · 정산 안내가 이 주소로 갑니다.": "The contract, tax invoice and settlement notices go to this address.",
  "콘텐츠 형식 *": "Content format *",
  "예) 세면대에 제품을 놓고 찍은 사진 한 장과 텍스처 클로즈업을 함께 올려 주세요.": "e.g. Please post one photo of the product placed on the sink together with a close-up of the texture.",
  "확정 보수": "Confirmed fee",
  "캠페인 정산": "Campaign settlement",
  "지급일은 콘텐츠를 올린 달의 다음 달 말일입니다. 세금 신고와 관련된 공제는 지급 단계에서 처리되며, 이 화면은 확정된 정산 금액을 그대로 보여 줍니다.": "The payout date is the last day of the month after the month the content was posted. Deductions related to tax filing are handled at the payment stage, and this screen shows the confirmed settlement amount exactly as it is.",
  "자": "characters",
  "본문에 의견": "Comment on the caption",
